set -euo pipefail
python3 - <<'PY'
import sqlite3,json,time
d=sqlite3.connect('file:/var/lib/news-flow/news-flow-runtime/write.sqlite?mode=ro',uri=True);d.row_factory=sqlite3.Row;now=int(time.time()*1000);hour=now-3600000
def rows(sql,args=()):return [dict(x) for x in d.execute(sql,args)]
print(json.dumps({'at':now,'articles':rows("SELECT (b.parse_key IS NOT NULL) backfill,a.parse_status,count(*) n,min(a.first_at) oldest_first_at,max(a.first_at) newest_first_at FROM article_links a LEFT JOIN news_category_backfill b ON b.parse_key=a.parse_key WHERE a.parse_status IN ('pending','queued','running') GROUP BY 1,2"),'recent_discoveries':rows("SELECT (b.parse_key IS NOT NULL) backfill,a.parse_status,count(*) n FROM article_links a LEFT JOIN news_category_backfill b ON b.parse_key=a.parse_key WHERE a.first_at>=? GROUP BY 1,2",[hour]),'recent_imports':rows('SELECT status,es_index,count(*) n FROM import_receipts WHERE imported_at>=? GROUP BY 1,2 ORDER BY n DESC LIMIT 12',[hour]),'recent_verified_dates':rows("SELECT substr(json_extract(details,'$.publishedDate'),1,10) published_day,count(*) n FROM events WHERE kind='verified' AND at>=? GROUP BY 1 ORDER BY n DESC LIMIT 12",[hour]),'task_queues':rows('SELECT role,state,count(*) n,min(created) oldest_created FROM tasks GROUP BY 1,2'),'homepages':rows("SELECT site,url,status,reason,last_at FROM seed_sources WHERE url IN ('https://vnexpress.net/','https://vnexpress.net/rss/tin-moi-nhat.rss','https://tuoitre.vn/','https://thanhnien.vn/','https://vietnamnet.vn/','https://dantri.com.vn/','https://cafef.vn/','https://quasa.io/')")},ensure_ascii=False))
PY
